using System.Windows; using Forms=System.Windows.Forms; namespace CloudServer; public partial class AdminWindow:Window { readonly StateStore store; public AdminWindow(StateStore s){InitializeComponent();store=s;AddUserButton.Click+=(_,__)=>AddUser();EditUserButton.Click+=(_,__)=>EditUser();DeleteUserButton.Click+=(_,__)=>DeleteUser();AddStorageButton.Click+=(_,__)=>AddStorage();Refresh();} void Refresh(){UserCount.Text=store.State.Users.Count.ToString();StorageCount.Text=store.State.Storage.Count.ToString();UsersGrid.ItemsSource=store.State.Users.Select(u=>new UserRow(u.Id,u.UserName,u.IsAdmin?"Administrator":"Benutzer",Format(u.QuotaBytes))).ToList();StorageGrid.ItemsSource=store.State.Storage.Select(x=>new StorageRow(x.Name,x.Role,store.State.Users.FirstOrDefault(u=>u.Id==x.UserId)?.UserName??"Gemeinsam")).ToList();} static string Format(long b)=>b<=0?"Unbegrenzt":b>=1099511627776L?$"{b/1099511627776d:N2} TB":$"{b/1073741824d:N0} GB"; void AddUser(){var d=new UserDialog{Owner=this};if(d.ShowDialog()!=true)return;store.State.Users.Add(new UserAccount{UserName=d.UserName,DisplayName=d.DisplayName,PasswordHash=StateStore.Hash(d.Password),QuotaBytes=d.QuotaBytes});store.Save();Refresh();} void EditUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null)return;var d=new UserDialog(u.UserName,u.DisplayName,u.QuotaBytes){Owner=this};if(d.ShowDialog()!=true)return;u.UserName=d.UserName;u.DisplayName=d.DisplayName;u.QuotaBytes=d.QuotaBytes;if(!string.IsNullOrWhiteSpace(d.Password))u.PasswordHash=StateStore.Hash(d.Password);store.Save();Refresh();} void DeleteUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null||u.IsAdmin)return;if(System.Windows.MessageBox.Show($"Benutzer {u.UserName} löschen?","Bestätigen",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;store.State.Users.Remove(u);store.Save();Refresh();} void AddStorage(){using var d=new Forms.FolderBrowserDialog{Description="Vorhandenen Ordner auswählen. Es wird nichts formatiert oder gelöscht."};if(d.ShowDialog()!=Forms.DialogResult.OK)return;var target=store.State.Users.FirstOrDefault(x=>!x.IsAdmin);store.State.Storage.Add(new StorageAssignment{Name=System.IO.Path.GetFileName(d.SelectedPath.TrimEnd(System.IO.Path.DirectorySeparatorChar)),Path=d.SelectedPath,Role="Personal",UserId=target?.Id,QuotaBytes=target?.QuotaBytes??0});store.Save();Refresh();} sealed record UserRow(string Id,string User,string Role,string Quota); sealed record StorageRow(string Name,string Role,string Assigned); }